    var rest = Array.prototype.slice.call(arguments, 2);
    try {
      var rewritten = proxied(url, method);
      if (rewritten !== url) {
        url = rewritten;
      }
    } catch (_) {}
    return nativeOpen.apply(this, [method, url].concat(rest));
