        const failedAssetUrls = [...responseFailures].sort();
        assertSceneEvidence(file, scene, failedAssetUrls);
        const screenshot = await cdp.send("Page.captureScreenshot", { format: "png", captureBeyondViewport: true }, sessionId);
        const screenshotFile = `${file.replace(/\.html$/, "")}-${viewport.id}.png`;
        await writeFile(join(outputDirectory, screenshotFile), Buffer.from(screenshot.data, "base64"));
